package com.configmonitor.app;
import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
public class AlarmRepeatTest {
 JSONObject down()throws Exception{JSONObject n=Parser.j("enabled",true,"state","bad","lastCheck",1000);for(int i=0;i<6;i++)Rules.apply(n,false,-1,1000);return n;}
 @Test public void repeatedAcknowledgementsRequireSixNewFailuresInBackground()throws Exception{JSONObject n=down();for(int cycle=0;cycle<4;cycle++){Rules.acknowledge(n);assertEquals("bad",n.getString("state"));assertEquals(0,n.getInt("failures"));assertFalse(AlarmRecovery.canDeliver(n,2000));for(int i=1;i<6;i++){assertFalse(Rules.apply(n,false,-1,2000+i));assertFalse(AlarmRecovery.missing(n,false,2000+i));}assertTrue(Rules.apply(n,false,-1,2006));assertTrue(AlarmRecovery.canDeliver(n,2006));}}
 @Test public void recoveryBreaksNewFailureWindow()throws Exception{JSONObject n=down();Rules.acknowledge(n);for(int i=0;i<4;i++)assertFalse(Rules.apply(n,false,-1,1100+i));assertFalse(Rules.apply(n,true,80,1200));for(int i=0;i<5;i++)assertFalse(Rules.apply(n,false,-1,1300+i));assertTrue(Rules.apply(n,false,-1,1400));}
 @Test public void suppressionStillRequiresFreshResultAfterExpiry()throws Exception{for(String key:new String[]{"snoozeUntil","maintenanceUntil"}){JSONObject n=down().put(key,2000);Rules.acknowledge(n);for(int i=0;i<8;i++)assertFalse(Rules.apply(n,false,-1,1200+i));assertFalse(AlarmRecovery.missing(n,false,2100));assertTrue(Rules.apply(n,false,-1,2200));n.put("lastCheck",2200);assertTrue(AlarmRecovery.canDeliver(n,2200));}}
 @Test public void activeAlarmDoesNotRaiseDuplicateOnEachCheck()throws Exception{JSONObject n=down();for(int i=0;i<10;i++)assertFalse(Rules.apply(n,false,-1,1100+i));Rules.acknowledge(n);for(int i=0;i<5;i++)assertFalse(Rules.apply(n,false,-1,1200+i));assertTrue(Rules.apply(n,false,-1,1300));assertFalse(Rules.apply(n,false,-1,1400));}
 @Test public void oldAcknowledgementIsMigratedToNewWindow()throws Exception{JSONObject n=new JSONObject(down().put("ack",true).toString());for(int i=0;i<5;i++)assertFalse(Rules.apply(n,false,-1,1500+i));assertTrue(Rules.apply(n,false,-1,1600));}
 @Test public void latencyAcknowledgementAlsoResetsItsThreshold()throws Exception{JSONObject n=Parser.j("enabled",true,"rules",Parser.j("failureLimit",6,"latencyEnabled",true,"latencyMs",700,"latencyStreak",3));for(int i=0;i<2;i++)assertFalse(Rules.apply(n,true,900,1000+i));assertTrue(Rules.apply(n,true,900,1100));Rules.acknowledge(n);for(int i=0;i<2;i++)assertFalse(Rules.apply(n,true,900,1200+i));assertTrue(Rules.apply(n,true,900,1300));}
 @Test public void customAndGlobalThresholdsAreRespected()throws Exception{for(int threshold:new int[]{1,2,6,12,100}){JSONObject n=down();n.put("rules",Parser.j("failureLimit",threshold));Rules.acknowledge(n);for(int i=1;i<=threshold;i++)assertEquals(i==threshold,Rules.apply(n,false,-1,2000+i));JSONObject global=down();Rules.acknowledge(global);for(int i=1;i<=threshold;i++)assertEquals(i==threshold,Rules.apply(global,false,-1,3000+i,threshold));}}
 @Test public void partialNewWindowSurvivesSerializationAndReopens()throws Exception{JSONObject n=down();Rules.acknowledge(n);for(int i=1;i<=6;i++){n=new JSONObject(n.toString());Rules.rearm(n);assertEquals(i==6,Rules.apply(n,false,-1,2000+i));}}
}
